public class Main {
    public static void main(String[] args) {
        Drawable d = new Circle();
        d.draw();
    }
}

interface Drawable {
    void draw();
    default void log() {
        System.out.println("Performing draw operation...");
    }
}

class Circle implements Drawable {
    public void draw() {
        log();
        System.out.println("Circle");
    }
}
